mod math {
    pub fn square(x: Int) -> Int { return x * x }
    pub fn cube(x: Int) -> Int { return x * x * x }
}

use math::square
use math::cube as third_power

fn main() {
    io.println("square(4) = {square(4)}")
    io.println("cube(4) = {third_power(4)}")
}
